UPDATE agent_skill
SET skill_version_id = CASE id

        WHEN #{binding.id} THEN #{binding.skillVersionId}

    END,
    enabled = CASE id

        WHEN #{binding.id} THEN #{binding.enabled}

    END,
    updated_at = CURRENT_TIMESTAMP
WHERE id IN

    #{binding.id}

UPDATE agent_skill relation
    INNER JOIN agent ON agent.id = relation.agent_id AND agent.deleted = 0
SET relation.skill_version_id = #{skillVersionId}
WHERE relation.skill_id = #{skillId}
  AND relation.enabled = 1
  AND agent.space_id = #{spaceId}
